<script setup lang="ts">
import {onMounted,ref} from 'vue'; import {useRoute,useRouter} from 'vue-router'; import {api,describe,projectRole} from '../api'; import type {Meeting,Draft} from '../types'
const route=useRoute(),router=useRouter(), project=String(route.params.projectId), root=`/api/projects/${project}/meeting-records`
const title=ref(''),content=ref(''),file=ref<File|null>(null),meeting=ref<Meeting|null>(null),error=ref(''),busy=ref(false), canWrite=ref(false)
onMounted(async()=>{try { canWrite.value=['OWNER','ADMIN','MEMBER'].includes(await projectRole(project)) } catch(e) {error.value=describe(e)} })
async function upload(kind:'text'|'file'){if(!canWrite.value)return;error.value='';busy.value=true;try{let body:BodyInit;if(kind==='text') body=JSON.stringify({title:title.value,content:content.value});else{if(!file.value)throw new Error('请选择文件');const data=new FormData();data.append('file',file.value);body=data}meeting.value=await api<Meeting>(`${root}/${kind==='file'?'files':'text'}`,{method:'POST',body})}catch(e){error.value=e instanceof Error&&e.message==='请选择文件'?e.message:describe(e)}finally{busy.value=false}}
async function draft(){if(!meeting.value)return;busy.value=true;error.value='';try{const result=await api<Draft>(`${root}/${meeting.value.id}/task-drafts`,{method:'POST'});await router.push(`/projects/${project}/drafts/${result.draft.id}`)}catch(e){error.value=describe(e)}finally{busy.value=false}}
function selectFile(e:Event){file.value=(e.target as HTMLInputElement).files?.[0] || null}
</script>
<template><div class="page-head"><div><p class="eyebrow">项目 {{project}} / 会议记录</p><h1>从会议开始</h1><p class="muted">导入记录，生成草稿，再由你确认每一项行动。</p></div><router-link class="button secondary" :to="`/projects/${project}/tasks`">查看正式任务 →</router-link></div><div class="steps"><span class="active">01 导入会议</span><span>02 审核草稿</span><span>03 提交任务</span></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="!canWrite" class="notice">当前角色不可导入或生成草稿，权限以服务端为准。</p><div class="columns"><section class="card"><h2>输入会议文本</h2><p class="muted">粘贴会议结论和行动项。</p><form @submit.prevent="upload('text')"><label>会议标题<input v-model.trim="title" required maxlength="255" placeholder="例如：项目周会"></label><label>会议内容<textarea v-model="content" required rows="11" placeholder="在此输入会议记录…"></textarea></label><button class="primary" :disabled="busy || !canWrite">{{busy?'处理中…':'导入会议文本'}}</button></form></section><div><section class="card"><h2>上传本地文件</h2><p class="muted">支持 TXT、Markdown、DOCX，最大 5 MB。</p><input type="file" accept=".txt,.md,.docx" @change="selectFile"><button class="secondary wide top" :disabled="busy || !file || !canWrite" @click="upload('file')">上传并导入</button></section><section v-if="meeting" class="card result"><p class="eyebrow">导入完成</p><h2>{{meeting.title}}</h2><p>记录 #{{meeting.id}} · {{meeting.sourceType}}</p><p>索引状态：<span class="badge">{{meeting.indexStatus}}</span></p><p v-if="meeting.indexFailureReason" class="error">{{meeting.indexFailureReason}}</p><p class="muted">生成草稿后可检查和修改，不会自动创建正式任务。</p><button class="primary wide" :disabled="busy || !canWrite" @click="draft">{{busy?'生成中…':'生成任务草稿 →'}}</button></section><section v-else class="card hint"><h2>接下来会发生什么？</h2><p>AI 提取行动项后，你可以逐条检查、修改或删除，再确认提交。</p></section></div></div></template>
